use kni_master::{otf::{OtfFont,ReadError},model::Op};
fn checksum(bytes:&[u8])->u32{bytes.chunks(4).fold(0u32,|v,b|{let mut w=[0;4];w[..b.len()].copy_from_slice(b);v.wrapping_add(u32::from_be_bytes(w))})}
fn sfnt(mut tables:Vec<([u8;4],Vec<u8>)>,signature:[u8;4])->Vec<u8>{tables.sort_by_key(|t|t.0);let n=tables.len();let mut out=vec![0;12+16*n];out[..4].copy_from_slice(&signature);out[4..6].copy_from_slice(&(n as u16).to_be_bytes());let power=1usize<<(usize::BITS-1-n.leading_zeros());out[6..8].copy_from_slice(&((power*16)as u16).to_be_bytes());out[8..10].copy_from_slice(&(power.trailing_zeros()as u16).to_be_bytes());out[10..12].copy_from_slice(&((n*16-power*16)as u16).to_be_bytes());let mut head_at=0;for(i,(tag,data))in tables.into_iter().enumerate(){while out.len()%4!=0{out.push(0)}let off=out.len();if tag==*b"head"{head_at=off;}let p=12+16*i;out[p..p+4].copy_from_slice(&tag);out[p+4..p+8].copy_from_slice(&checksum(&data).to_be_bytes());out[p+8..p+12].copy_from_slice(&(off as u32).to_be_bytes());out[p+12..p+16].copy_from_slice(&(data.len()as u32).to_be_bytes());out.extend(data);}while out.len()%4!=0{out.push(0)}let adjustment=0xB1B0AFBAu32.wrapping_sub(checksum(&out));out[head_at+8..head_at+12].copy_from_slice(&adjustment.to_be_bytes());out}
fn table_font(glyph:Vec<u8>,long:bool)->Vec<u8>{let mut head=vec![0u8;54];head[..4].copy_from_slice(&0x00010000u32.to_be_bytes());head[12..16].copy_from_slice(&0x5F0F3CF5u32.to_be_bytes());head[18..20].copy_from_slice(&1000u16.to_be_bytes());head[50..52].copy_from_slice(&(if long{1u16}else{0}).to_be_bytes());let mut hhea=vec![0u8;36];hhea[..4].copy_from_slice(&0x00010000u32.to_be_bytes());hhea[34..36].copy_from_slice(&1u16.to_be_bytes());let mut maxp=vec![0u8;32];maxp[..4].copy_from_slice(&0x00010000u32.to_be_bytes());maxp[4..6].copy_from_slice(&1u16.to_be_bytes());let mut glyf=glyph;if glyf.len()%2!=0{glyf.push(0)}let loca=if long{[0u32.to_be_bytes(),(glyf.len()as u32).to_be_bytes()].concat()}else{[0u16.to_be_bytes(),((glyf.len()/2)as u16).to_be_bytes()].concat()};sfnt(vec![(*b"head",head),(*b"hhea",hhea),(*b"maxp",maxp),(*b"hmtx",vec![1,244,0,0]),(*b"loca",loca),(*b"glyf",glyf)],[0,1,0,0])}
fn simple(points:&[(i16,i16,bool)])->Vec<u8>{let mut out=vec![0u8;10];out[..2].copy_from_slice(&1i16.to_be_bytes());out.extend(((points.len()-1)as u16).to_be_bytes());out.extend(0u16.to_be_bytes());out.extend(points.iter().map(|p|u8::from(p.2)));for axis in 0..2{let mut prev=0i16;for p in points{let v=if axis==0{p.0}else{p.1};out.extend((v-prev).to_be_bytes());prev=v;}}out}
#[test]fn simple_oncurve_and_both_loca_formats(){for long in [false,true]{let data=table_font(simple(&[(0,0,true),(10,0,true),(10,10,true),(0,10,true)]),long);let font=OtfFont::parse(&data).unwrap();let g=font.glyph(0).unwrap();assert_eq!(g.advance,500.);assert_eq!(g.upm,1000.);assert_eq!(g.contours[0].ops,vec![Op::Move((0.,0.)),Op::Line((10.,0.)),Op::Line((10.,10.)),Op::Line((0.,10.)),Op::Line((0.,0.)),Op::Close]);}}
#[test]fn implied_midpoints_degree_elevation_and_offcurve_start(){let data=table_font(simple(&[(0,0,false),(12,12,false),(24,0,false)]),true);let g=OtfFont::parse(&data).unwrap().glyph(0).unwrap();let ops=&g.contours[0].ops;assert_eq!(ops[0],Op::Move((12.,0.)));assert_eq!(ops.len(),5);assert!(ops[1..4].iter().all(|op|matches!(op,Op::Curve(..))));assert_eq!(ops[4],Op::Close);if let Op::Curve(c1,c2,end)=ops[1]{assert_eq!(c1,(4.,0.));assert_eq!(c2,(2.,2.));assert_eq!(end,(6.,6.));}else{panic!()}}
#[test]fn empty_glyph_and_truncated_composite(){let bytes=table_font(vec![],false);assert!(OtfFont::parse(&bytes).unwrap().glyph(0).unwrap().contours.is_empty());let mut g=vec![0u8;10];g[..2].copy_from_slice(&(-1i16).to_be_bytes());let bytes=table_font(g,true);assert!(matches!(OtfFont::parse(&bytes).unwrap().glyph(0),Err(ReadError::Truncated(_))));}
#[test]fn truncation_and_flag_repeat_overrun_refuse(){let bytes=table_font(vec![0;2],true);assert!(matches!(OtfFont::parse(&bytes).unwrap().glyph(0),Err(ReadError::Truncated(_))));let mut g=vec![0u8;10];g[..2].copy_from_slice(&1i16.to_be_bytes());g.extend(0u16.to_be_bytes());g.extend(0u16.to_be_bytes());g.extend([9,1]);let bytes=table_font(g,true);assert!(matches!(OtfFont::parse(&bytes).unwrap().glyph(0),Err(ReadError::BadGlyf{..})));}
#[test]fn directory_and_checksum_are_valid(){let b=table_font(simple(&[(0,0,true)]),true);assert_eq!(checksum(&b),0xB1B0AFBA);let n=u16::from_be_bytes([b[4],b[5]])as usize;let mut previous=[0;4];for i in 0..n{let p=12+16*i;let tag:[u8;4]=b[p..p+4].try_into().unwrap();assert!(tag>previous);previous=tag;let off=u32::from_be_bytes(b[p+8..p+12].try_into().unwrap())as usize;let len=u32::from_be_bytes(b[p+12..p+16].try_into().unwrap())as usize;assert_eq!(off%4,0);let mut data=b[off..off+len].to_vec();if tag==*b"head"{data[8..12].fill(0)}assert_eq!(checksum(&data),u32::from_be_bytes(b[p+4..p+8].try_into().unwrap()));}}
#[test]fn loca_extent_and_order_guards(){for long in [false,true]{let b=table_font(simple(&[(0,0,true)]),long);let n=u16::from_be_bytes([b[4],b[5]])as usize;let rec=(0..n).map(|i|12+16*i).find(|p|&b[*p..*p+4]==b"loca").unwrap();let off=u32::from_be_bytes(b[rec+8..rec+12].try_into().unwrap())as usize;for reversed in [false,true]{let mut b=b.clone();if long{b[off..off+4].copy_from_slice(&(if reversed{4u32}else{0}).to_be_bytes());b[off+4..off+8].copy_from_slice(&(if reversed{0u32}else{u32::MAX}).to_be_bytes());}else{b[off..off+2].copy_from_slice(&(if reversed{4u16}else{0}).to_be_bytes());b[off+2..off+4].copy_from_slice(&(if reversed{0u16}else{u16::MAX}).to_be_bytes());}assert!(matches!(OtfFont::parse(&b),Err(ReadError::Truncated(_))));}}}
fn cmap65()->Vec<u8>{let mut d=vec![0u8;40];d[2..4].copy_from_slice(&1u16.to_be_bytes());d[4..6].copy_from_slice(&3u16.to_be_bytes());d[6..8].copy_from_slice(&10u16.to_be_bytes());d[8..12].copy_from_slice(&12u32.to_be_bytes());d[12..14].copy_from_slice(&12u16.to_be_bytes());d[16..20].copy_from_slice(&28u32.to_be_bytes());d[24..28].copy_from_slice(&1u32.to_be_bytes());d[28..32].copy_from_slice(&65u32.to_be_bytes());d[32..36].copy_from_slice(&65u32.to_be_bytes());d}
fn tables_of(b:&[u8])->Vec<([u8;4],Vec<u8>)>{let n=u16::from_be_bytes([b[4],b[5]])as usize;(0..n).map(|i|{let p=12+16*i;let tag=b[p..p+4].try_into().unwrap();let o=u32::from_be_bytes(b[p+8..p+12].try_into().unwrap())as usize;let n=u32::from_be_bytes(b[p+12..p+16].try_into().unwrap())as usize;let mut d=b[o..o+n].to_vec();if tag==*b"head"{d[8..12].fill(0)}(tag,d)}).collect()}
fn mapped(g:Vec<u8>)->Vec<u8>{let mut ts=tables_of(&table_font(g,true));ts.push((*b"cmap",cmap65()));sfnt(ts,[0,1,0,0])}
fn cff_candidate()->Vec<u8>{let mut ts=tables_of(&table_font(vec![],true));ts.retain(|(tag,_)|tag!=b"glyf"&&tag!=b"loca");let cs=vec![139,139,21,159,139,139,159,119,139,139,119,5,14];let mut c=vec![1,0,4,4,0,1,1,1,2,b'X',0,1,1,1,3,160,17,0,0,0,0];c.extend([0,1,1,1,(cs.len()+1)as u8]);c.extend(cs);ts.push((*b"CFF ",c));ts.push((*b"cmap",cmap65()));sfnt(ts,*b"OTTO")}
#[test]fn bridge_tt_reference_cff_candidate_nonzero(){use kni_master::{vector_font_rows::*,validate::Params};let r=mapped(simple(&[(0,0,true),(10,0,true),(10,10,true),(0,10,true)]));let c=cff_candidate();let rf=OtfFont::parse(&r).unwrap();let cf=OtfFont::parse(&c).unwrap();let rows=measure_font_cmap(&rf,&cf,Params::from_rounding(0.5)).unwrap();let m=rows.rows[0].metrics.as_ref().unwrap();assert!((m.symmetric_difference_area-300.).abs()<1e-9);assert!((m.hausdorff-(200f64).sqrt()).abs()<1e-9);let s=measurements_json(&rows,MeasurementContext{reference_sha256:&"a".repeat(64),candidate_sha256:&"b".repeat(64),upm:1000.,params:Params::from_rounding(0.5)}).unwrap();assert!(s.contains("kni.vector-measurements.v3"));}
#[test]fn bridge_empty_and_bad_glyph_keep_keyset(){use kni_master::{vector_font_rows::*,validate::Params};for glyph in [vec![],vec![0,0]]{let r=mapped(glyph);let f=OtfFont::parse(&r).unwrap();let rows=measure_font_cmap(&f,&f,Params::from_rounding(0.5)).unwrap();assert_eq!(rows.rows.len(),1);assert_eq!(rows.rows[0].codepoint,65);assert!(rows.rows[0].metrics.is_none());let s=measurements_json(&rows,MeasurementContext{reference_sha256:&"a".repeat(64),candidate_sha256:&"b".repeat(64),upm:1000.,params:Params::from_rounding(0.5)}).unwrap();assert!(s.contains("\"n_a_count\":1"));assert!(!s.contains("symmetric_difference_area"));}}
#[test]fn bridge_error_paths_and_serialization_context(){use kni_master::{vector_font_rows::*,validate::Params};let valid=mapped(simple(&[(0,0,true),(10,0,true),(10,10,true),(0,10,true)]));let reference=OtfFont::parse(&valid).unwrap();let candidate_bytes=table_font(simple(&[(0,0,true)]),true);let candidate=OtfFont::parse(&candidate_bytes).unwrap();let p=Params::from_rounding(0.5);let batch=measure_font_cmap(&reference,&candidate,p).unwrap();let u=batch.rows[0].unavailable.as_ref().unwrap();assert_eq!(u.reason,"candidate_missing");assert_eq!(u.reason_class,ReasonClass::CandidateMissingOrEmpty);assert_eq!(u.font,FontSide::Candidate);assert!(matches!(measure_font_cmap(&candidate,&candidate,p),Err(FontRowError::EmptyCmap)));assert!(matches!(measure_font_cmap(&reference,&candidate,Params::from_rounding(f64::NAN)),Err(FontRowError::InvalidParams)));let mut ts=tables_of(&valid);let head=ts.iter_mut().find(|t|t.0==*b"head").unwrap();head.1[18..20].copy_from_slice(&2000u16.to_be_bytes());let b=sfnt(ts,[0,1,0,0]);let f=OtfFont::parse(&b).unwrap();assert!(matches!(measure_font_cmap(&reference,&f,p),Err(FontRowError::FrameMismatch)));let a="a".repeat(64);let b="b".repeat(64);assert!(matches!(measurements_json(&batch,MeasurementContext{reference_sha256:&a,candidate_sha256:&a,upm:1000.,params:p}),Err(FontRowError::IdenticalHashes)));assert!(matches!(measurements_json(&batch,MeasurementContext{reference_sha256:&a,candidate_sha256:&b,upm:2000.,params:p}),Err(FontRowError::FrameMismatch)));assert!(matches!(measurements_json(&batch,MeasurementContext{reference_sha256:&a,candidate_sha256:&b,upm:1000.,params:Params::from_rounding(1.)}),Err(FontRowError::FrameMismatch)));assert!(matches!(measurements_json(&batch,MeasurementContext{reference_sha256:"bad",candidate_sha256:&b,upm:1000.,params:p}),Err(FontRowError::InvalidHash)));let s=measurements_json(&batch,MeasurementContext{reference_sha256:&a,candidate_sha256:&b,upm:1000.,params:p}).unwrap();assert!(s.contains("\"candidate_missing_or_empty\":1"));assert!(s.contains("\"reason\":\"candidate_missing\""));}
#[test]fn serialization_duplicate_and_inconsistent_rows(){use kni_master::{vector_font_rows::*,validate::Params};let r=mapped(simple(&[(0,0,true),(10,0,true),(10,10,true),(0,10,true)]));let f=OtfFont::parse(&r).unwrap();let p=Params::from_rounding(0.5);let mut b=measure_font_cmap(&f,&f,p).unwrap();let a="a".repeat(64);let c="c".repeat(64);b.rows.push(b.rows[0].clone());assert!(matches!(measurements_json(&b,MeasurementContext{reference_sha256:&a,candidate_sha256:&c,upm:1000.,params:p}),Err(FontRowError::DuplicateCodepoint(65))));b.rows.pop();b.rows[0].metrics=None;assert!(matches!(measurements_json(&b,MeasurementContext{reference_sha256:&a,candidate_sha256:&c,upm:1000.,params:p}),Err(FontRowError::InvalidRow(65))));}
